package com.kuaixietech.integrationsdk.paymentprotocol;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.*;
import com.kuaixietech.integration.IntegrationHttp;
import com.kuaixietech.integrationsdk.social.SocialServiceContext;
import java.math.*;
import java.net.*;
import java.net.http.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.stream.Collectors;
import org.springframework.stereotype.Component;
/** Official signed read-only payment/refund inspection with strict sandbox/live endpoints and receipt modes. */
@Component
public class AlipayExplicitModeProtocol {
 private final IntegrationHttp http;private final ObjectMapper json;private final Clock clock;
 public record TradeReceipt(String mode,String appId,String reference,String transactionId,BigInteger amountMinor,String status){public boolean realFundsConfirmed(){return mode.equals("LIVE")&&Set.of("TRADE_SUCCESS","TRADE_FINISHED").contains(status);}}
 public record RefundReceipt(String mode,String appId,String reference,String transactionId,String refundReference,BigInteger amountMinor,String status){public boolean realFundsConfirmed(){return mode.equals("LIVE")&&status.equals("REFUND_SUCCESS");}}
 @org.springframework.beans.factory.annotation.Autowired public AlipayExplicitModeProtocol(IntegrationHttp http,ObjectMapper mapper){this(http,mapper,Clock.systemUTC());}
 public AlipayExplicitModeProtocol(IntegrationHttp http,ObjectMapper mapper,Clock clock){this.http=http;this.json=mapper.copy().enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);this.clock=clock;}
 public TradeReceipt trade(SocialServiceContext context,String reference){context.require("ALIPAY","alipay",true);reference(reference);JsonNode result=call(context,"alipay.trade.query","alipay_trade_query_response",Map.of("out_trade_no",reference));if(!reference.equals(result.path("out_trade_no").asText()))throw new IllegalStateException("ALIPAY_RECEIPT_REFERENCE_MISMATCH");String transaction=result.path("trade_no").asText(),status=result.path("trade_status").asText();if(transaction.isBlank()||transaction.length()>128||!Set.of("WAIT_BUYER_PAY","TRADE_CLOSED","TRADE_SUCCESS","TRADE_FINISHED").contains(status))throw new IllegalStateException("ALIPAY_RECEIPT_INVALID");if(result.hasNonNull("trans_currency")&&!result.path("trans_currency").asText().equals("CNY"))throw new IllegalStateException("ALIPAY_CURRENCY_UNSUPPORTED");return new TradeReceipt(context.mode(),context.required("app_id"),reference,transaction,minor(result.path("total_amount").asText()),status);}
 public RefundReceipt refund(SocialServiceContext context,String reference,String refundReference){context.require("ALIPAY","alipay",true);reference(reference);reference(refundReference);JsonNode result=call(context,"alipay.trade.fastpay.refund.query","alipay_trade_fastpay_refund_query_response",Map.of("out_trade_no",reference,"out_request_no",refundReference));if(!reference.equals(result.path("out_trade_no").asText())||!refundReference.equals(result.path("out_request_no").asText()))throw new IllegalStateException("ALIPAY_RECEIPT_REFERENCE_MISMATCH");String transaction=result.path("trade_no").asText(),status=result.path("refund_status").asText();if(transaction.isBlank()||transaction.length()>128||!"REFUND_SUCCESS".equals(status))throw new IllegalStateException("ALIPAY_REFUND_UNCONFIRMED");return new RefundReceipt(context.mode(),context.required("app_id"),reference,transaction,refundReference,minor(result.path("refund_amount").asText()),status);}
 private JsonNode call(SocialServiceContext context,String method,String key,Map<String,String> content){try{String app=context.required("app_id");if(!app.matches("[0-9]{8,32}"))throw new IllegalArgumentException("ALIPAY_APP_ID_INVALID");PrivateKey privateKey=privateKey(context.required("private_key_pem"));PublicKey publicKey=publicKey(context.required("platform_public_key_pem"));var params=new TreeMap<String,String>();params.put("app_id",app);params.put("method",method);params.put("format","JSON");params.put("charset","utf-8");params.put("sign_type","RSA2");params.put("timestamp",DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss").withZone(ZoneId.of("Asia/Shanghai")).format(clock.instant()));params.put("version","1.0");params.put("biz_content",json.writeValueAsString(content));String canonical=params.entrySet().stream().map(e->e.getKey()+"="+e.getValue()).collect(Collectors.joining("&"));var signer=Signature.getInstance("SHA256withRSA");signer.initSign(privateKey);signer.update(canonical.getBytes(StandardCharsets.UTF_8));params.put("sign",Base64.getEncoder().encodeToString(signer.sign()));String body=params.entrySet().stream().map(e->encode(e.getKey())+"="+encode(e.getValue())).collect(Collectors.joining("&"));String response=http.send(HttpRequest.newBuilder(PaymentEnvironmentPolicy.alipayGateway(context.mode())).timeout(Duration.ofSeconds(15)).header("Content-Type","application/x-www-form-urlencoded;charset=UTF-8").POST(HttpRequest.BodyPublishers.ofString(body)).build());JsonNode envelope=json.readTree(response);if(envelope==null||!envelope.isObject()||!envelope.path("sign").isTextual()||envelope.hasNonNull("sign_type")&&!"RSA2".equals(envelope.path("sign_type").asText()))throw new IllegalStateException("ALIPAY_RESPONSE_INVALID");String signed=exactObject(response,key);var verifier=Signature.getInstance("SHA256withRSA");verifier.initVerify(publicKey);verifier.update(signed.getBytes(StandardCharsets.UTF_8));if(!verifier.verify(Base64.getDecoder().decode(envelope.path("sign").asText())))throw new IllegalStateException("ALIPAY_SIGNATURE_REJECTED");JsonNode result=envelope.path(key);if(!"10000".equals(result.path("code").asText()))throw new IllegalStateException("ALIPAY_PROVIDER_REJECTED");return result;}catch(IllegalArgumentException|IllegalStateException e){throw e;}catch(Exception e){throw new IllegalStateException("ALIPAY_PROTOCOL_UNCONFIRMED");}}
 private String exactObject(String body,String field)throws Exception{try(var parser=json.getFactory().createParser(body)){if(parser.nextToken()!=JsonToken.START_OBJECT)throw new IllegalArgumentException();while(parser.nextToken()!=JsonToken.END_OBJECT){String name=parser.currentName();JsonToken token=parser.nextToken();if(field.equals(name)){if(token!=JsonToken.START_OBJECT)throw new IllegalArgumentException();int start=(int)parser.currentTokenLocation().getCharOffset();parser.skipChildren();int end=(int)parser.currentTokenLocation().getCharOffset()+1;return body.substring(start,end);}parser.skipChildren();}}throw new IllegalStateException("ALIPAY_SIGNED_OBJECT_MISSING");}
 private static byte[] pem(String value){if(value.length()>16000)throw new IllegalArgumentException("ALIPAY_KEY_TOO_LARGE");return Base64.getDecoder().decode(value.replaceAll("-----[^-]+-----","").replaceAll("\\s", ""));}
 private static PrivateKey privateKey(String value)throws Exception{return KeyFactory.getInstance("RSA").generatePrivate(new PKCS8EncodedKeySpec(pem(value)));}
 private static PublicKey publicKey(String value)throws Exception{if(value.contains("BEGIN CERTIFICATE")){try(var in=new java.io.ByteArrayInputStream(value.getBytes(StandardCharsets.US_ASCII))){var certificate=(java.security.cert.X509Certificate)java.security.cert.CertificateFactory.getInstance("X.509").generateCertificate(in);certificate.checkValidity();return certificate.getPublicKey();}}return KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(pem(value)));}
 private static BigInteger minor(String text){try{BigInteger value=new BigDecimal(text).movePointRight(2).toBigIntegerExact();if(value.signum()<0)throw new IllegalArgumentException();return value;}catch(Exception e){throw new IllegalStateException("ALIPAY_AMOUNT_INVALID");}}
 private static void reference(String reference){if(reference==null||!reference.matches("[A-Za-z0-9_-]{1,64}"))throw new IllegalArgumentException("ALIPAY_REFERENCE_INVALID");}
 private static String encode(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8);}
}
